export interface ServiceOffering {
  id: string | number;
  type?: string | null;
  status?: boolean | number | null;
}

/**
 * Phase 1 launches passenger rides only. Parcel and Freight stay configured and
 * bookable on the backend, but the Dropa2z Rider app does not surface them yet.
 *
 * To launch another offering, add its service `type` here. The backend remains
 * the source of truth: a service listed here still only appears when the API
 * returns it as enabled.
 */
export const LAUNCHED_SERVICE_TYPES: readonly string[] = ["cab"];

export const getLaunchedServices = <T extends ServiceOffering>(
  services: readonly T[] | null | undefined,
): T[] => {
  if (!services) {
    return [];
  }

  return services.filter(service => {
    const type = service.type?.trim().toLowerCase() ?? "";
    return LAUNCHED_SERVICE_TYPES.includes(type);
  });
};
